import itertools

def get_f(x, y, z, a, b, c):
    return abs(x + y - (a + b)) + abs(y + z - (b + c)) + abs(z + x - (c + a))

def solve():
    # All possible (x, y, z)
    P = list(itertools.product(range(10), repeat=3))
    # All possible (a, b, c)
    Q_all = list(itertools.product(range(10), repeat=3))

    # Current groups of triplets
    groups = [P]

    # To store selected questions
    selected_questions = []

    for q_idx in range(3):
        best_q = None
        min_pairs = float('inf')

        # We can't iterate over all Q_all for every group, 
        # but we can iterate over all Q_all and see how it splits the groups.
        for q in Q_all:
            current_pairs = 0
            for group in groups:
                # For each group, how many pairs are not distinguished?
                splits = {}
                for p in group:
                    val = get_f(p[0], p[1], p[2], q[0], q[1], q[2])
                    splits[val] = splits.get(val, 0) + 1
                for count in splits.values():
                    current_pairs += count * (count - 1) // 2

            if current_pairs < min_pairs:
                min_pairs = current_pairs
                best_q = q
                if min_pairs == 0:
                    break

        selected_questions.append(best_q)

        # Update groups based on best_q
        new_groups = []
        for group in groups:
            splits = {}
            for p in group:
                val = get_f(p[0], p[1], p[2], best_q[0], best_q[1], best_q[2])
                if val not in splits:
                    splits[val] = []
                splits[val].append(p)
            for s_group in splits.values():
                new_groups.append(s_group)
        groups = new_groups

        print(f"Question {q_idx+1}: {best_q}, pairs remaining: {min_pairs}")
        if min_pairs == 0:
            print(f"All distinguished after {q_idx+1} questions!")
            return q_idx + 1

    return 4 # If 3 were not enough in this greedy search

