import random

def get_f(x, y, z, a, b, c):
    return abs(x + y - (a + b)) + abs(y + z - (b + c)) + abs(z + x - (c + a))

def count_undistinguished_pairs(P, Q_set):
    # P is the list of (x, y, z)
    # Q_set is the list of (a, b, c)
    groups = {p: [] for p in P}
    for q in Q_set:
        for p in P:
            val = get_f(p[0], p[1], p[2], q[0], q[1], q[2])
            groups[p].append(val)

    # Now we count how many points have the same signature
    signatures = {}
    for p in P:
        sig = tuple(groups[p])
        signatures[sig] = signatures.get(sig, 0) + 1

    pairs = 0
    for count in signatures.values():
        pairs += count * (count - 1) // 2
    return pairs

def solve_randomized():
    P = list(itertools.product(range(10), repeat=3))
    Q_all = list(itertools.product(range(10), repeat=3))

    best_pairs = float('inf')
    best_Q_set = []

    # Try random sets and then local improvement
    for _ in range(100):
        Q_set = random.sample(Q_all, 3)
        pairs = count_undistinguished_pairs(P, Q_set)

        # Local improvement
        improved = True
        while improved:
            improved = False
            for i in range(3):
                current_q = Q_set[i]
                # Try replacing current_q with a few other random questions
                for _ in range(20):
                    new_q = random.choice(Q_all)
                    new_Q_set = list(Q_set)
                    new_Q_set[i] = new_q
                    new_pairs = count_undistinguished_pairs(P, new_Q_set)
                    if new_pairs < pairs:
                        pairs = new_pairs
                        Q_set[i] = new_q
                        improved = True
                        if pairs == 0:
                            return 3, Q_set

        if pairs < best_pairs:
            best_pairs = pairs
            best_Q_set = Q_set
            if best_pairs == 0:
                return 3, best_Q_set

    return None, best_Q_set

